import {observerStatus,type ObserverStatus} from "./decision-diagnostics";
import type {ReplayObservation,ResponseComponent} from "./contextual-replay";
import type {ResponseModel} from "./contextual-response";
import type { Policy } from "./bot";
import { createEquityPolicy, type EquityPolicyOptions } from "./equity-policy";
import { OpponentModel, type ActionClass } from "./opponent";
import type { ForecastRecord } from "./forecast-diagnostics";
import { handFeatures, decisionContext } from "./hand-features";
import { RangeBeliefs } from "./range-beliefs";
import { evaluateRiverActions, type RiverResult } from "./river-ev";
import type { Card, Street } from "./types";
import type { PublicView } from "./view";

type Evidence = { seat: number; street: Street; board: Card[]; facing: boolean; action: ActionClass };
export function createAdaptivePolicy(options: Omit<EquityPolicyOptions,"rangeFor"> & { priorStrength?: number; learn?: boolean; styleRetention?: number; riverRiskPenalty?: number; riverSamples?: number | false; onRiverDecision?: (result: RiverResult) => void; flopUniformWeight?: number; responseModel?:ResponseModel; onReplay?: (event:ReplayObservation)=>void; onPrediction?: (record: ForecastRecord & {facing:boolean;observerStatus:ObserverStatus}) => void } = {}) {
  const learn=options.learn??false;
  const retention=options.styleRetention??1;
  if(!Number.isFinite(retention)||retention<0||retention>1)throw new Error("Style retention must be between zero and one.");
  const model=new OpponentModel(options.priorStrength);
  let ids:string[]=[];
  let replayOrder=0;
  let hand=-1, count=0, reveals=0, inferences=0;
  const beliefs=new Map<number,RangeBeliefs>();
  let evidence:Evidence[]=[];
  const revealedEvidence: {event:Evidence; cards:[Card,Card]}[]=[];
  const knownCards=(view:PublicView)=>[...view.board,...view.seats.flatMap(s=>Array.isArray(s.hole)?s.hole:[])];
  const beliefFor=(seat:number)=>{
    let belief=beliefs.get(seat);
    if(!belief) {belief=new RangeBeliefs(undefined,options.flopUniformWeight??0,options.responseModel);beliefs.set(seat,belief);}
    return belief;
  };
  const ensureHand=(view:PublicView)=>{
    if(hand===view.handNumber)return;
    hand=view.handNumber;for(const belief of beliefs.values())belief.newHand(!learn,retention);evidence=[];
  };
  const control=createEquityPolicy({...options,rangeFor:(view,seat)=>{
    ensureHand(view);const belief=beliefFor(seat);belief.condition(knownCards(view));return belief.mixture();
  }});
  const policy:Policy=Object.assign((view:PublicView)=>{
    ensureHand(view);
    if(view.street==="river" && options.riverSamples!==false) {
      for(const opponent of view.seats.filter(s=>s.inHand&&!s.folded&&s.seat!==view.toAct))beliefFor(opponent.seat).condition(knownCards(view));
      const result=evaluateRiverActions(view,{samples:options.riverSamples??64,riskPenalty:options.riverRiskPenalty,seed:(options.seed??1)^Math.imul(view.handNumber,31)^view.log.length,
        rangeFor:seat=>beliefFor(seat).mixture(),styleFor:(seat,cards)=>beliefFor(seat).typeWeightsGiven(cards)});
      options.onRiverDecision?.(result);return result.best;
    }
    return control(view);
  },{
    startSession:(joinIds:string[])=>{
      replayOrder=0;ids=[...joinIds];model.startSession(ids);hand=-1;count=0;reveals=0;inferences=0;beliefs.clear();evidence=[];revealedEvidence.length=0;
    },
    observe:(before:PublicView,after:PublicView)=>{
      ensureHand(before);
      const seat=before.toAct;
      if(seat===null || before.street===null)return;
      // The observer's own cards are private to it; exclude its actions from opponent learning.
      if(Array.isArray(before.seats[seat]!.hole)) {if(after.phase==="complete")learnReveals(after);return;}
      const currentBet=before.betting?.currentBet??Math.max(...before.seats.map(s=>s.streetCommitted));
      const facing=currentBet>before.seats[seat]!.streetCommitted;
      const entry=after.log.findLast(e=>e.seat===seat && e.street===before.street && ["fold","check","call","bet","raise","all_in"].includes(e.action));
      if(!entry)throw new Error("Missing action observation.");
      const action:ActionClass=entry.action==="fold"?"fold":entry.raiseTo!==null && entry.raiseTo>currentBet?"aggressive":"passive";
      const event:Evidence={seat,street:before.street,board:[...before.board],facing,action};
      const belief=beliefFor(seat);
      belief.condition(knownCards(before));
      let components:ResponseComponent[]|undefined;
      const probabilities=belief.observe(before.board,decisionContext(before,seat),action,options.onReplay&&before.street==="flop"?c=>{components=c;}:undefined);
      if(options.onReplay){
        const observer=before.seats.find(s=>s.seat!==seat&&Array.isArray(s.hole)&&s.hole.length===2);
        if(!observer||!Array.isArray(observer.hole))throw new Error("Observer blockers missing.");
        options.onReplay({match:0,hand:before.handNumber,seat,order:replayOrder++,board:[...before.board],known:[...before.board,...observer.hole],context:decisionContext(before,seat),actual:action,...(components?{components}:{})});
      }
      if(options.onPrediction) {
        const observer=before.seats.find(s=>s.seat!==seat&&Array.isArray(s.hole)&&s.hole.length===2);
        if(!observer)throw new Error("Observer missing for forecast exposure.");
        const hole=observer.hole;
        const features=Array.isArray(hole)?handFeatures([hole[0]!,hole[1]!],before.board):null;
        const paired=new Set(before.board.map(c=>c[0])).size<before.board.length;
        const suited=["c","d","h","s"].some(suit=>before.board.filter(c=>c[1]===suit).length>=3);
        options.onPrediction({observerStatus:observerStatus(observer),street:before.street,probabilities,actual:action,facing,seat,opponentName:before.seats[seat]!.name,hand:before.handNumber,context:decisionContext(before,seat),observerGroup:features?.group??"unknown",observerDraw:features?.draw??false,boardTexture:`${paired?"paired":"unpaired"}:${suited?"three-suited":"mixed"}`,livePlayers:before.seats.filter(s=>s.inHand&&!s.folded).length});
      }
      inferences++;
      if(learn) {model.record(ids[seat]!,before.street,facing,action);count++;}
      if(learn)evidence.push(event);
      if(after.phase==="complete") learnReveals(after);
    }
  });
  function learnReveals(view:PublicView):void {
    if(!learn)return;
    const processed=new Set<number>();
    for(const event of evidence) {
      if(processed.has(event.seat))continue;
      processed.add(event.seat);
      const hole=view.seats[event.seat]!.hole;
      if(!Array.isArray(hole)||hole.length!==2)continue;
      const belief=beliefFor(event.seat);
      // Other revealed hands and the board remove impossible combinations, but not this player's revealed cards.
      const known=[...view.board,...view.seats.flatMap(s=>s.seat!==event.seat && Array.isArray(s.hole)?s.hole:[])];
      belief.condition(known);
      belief.reveal([hole[0]!,hole[1]!]);
    }
    for(const event of evidence) {
      const hole=view.seats[event.seat]!.hole;
      if(!Array.isArray(hole)||hole.length!==2)continue;
      revealedEvidence.push({event:{...event,board:[...event.board]},cards:[hole[0]!,hole[1]!]});
      reveals++;
    }
  }
  return {policy,model,observations:()=>count,revealedActions:()=>reveals,inferences:()=>inferences, revealedEvidence:()=>structuredClone(revealedEvidence),typeWeights:(seat:number)=>beliefFor(seat).typeWeights()};
}

